<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {workbenchRequest,requestChat} from '../lib/backends'
const props=defineProps({settings:Object})
const emit=defineEmits(['openExample'])
const data=ref(null),loading=ref(false),error=ref(''),running=ref(false),progress=ref(''),lastUpdated=ref('')
const totals=computed(()=>data.value?.execution_calls?.totals||{})
const sourceNames={synthetic_example:'合成示例 · 真实调用',historical_practice:'历史数据练习',historical_review:'客户评价翻译',local_workbench:'本地工作台'}
const exampleNames={late:'物流晚到示例',missing:'缺件核验示例',knowledge:'规则解释示例'}
const stateNames={completed:'已完成',failed:'执行异常',degraded:'部分完成',running:'执行中',unknown:'状态待核对',interrupted:'已中断'}
const agentNames={general:'通用客服',technical:'技术支持',billing:'账单售后',general_0:'通用客服',technical_0:'技术支持',billing_0:'账单售后'}
const display=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—'
let timer=null,disposed=false
async function refresh(){if(loading.value||disposed)return;loading.value=true;try{const value=await workbenchRequest(props.settings,'/monitor?user_id='+encodeURIComponent(props.settings.userId));if(disposed)return;data.value=value;lastUpdated.value=new Date().toISOString();error.value=''}catch(e){if(!disposed)error.value=e.message}finally{loading.value=false}}
const prompts={late:'请依据当前演示案例的已知信息，写一段给客户的简短答复，明确仍需核实的内容，不推断实际赔付。',missing:'根据这条缺件投诉的上下文，写一段简短答复，说明需要补充的信息。不作执行承诺。',knowledge:'请根据当前演示规则，用两句话解释下一步需要核实的内容，保留尚未确认的事项。'}
async function runExamples(){if(running.value)return;running.value=true;error.value='';let completed=0;try{const demos=await workbenchRequest(props.settings,'/demos/ensure','POST',{user_id:props.settings.userId});for(const item of demos.cases){if(disposed)break;progress.value='正在执行示例 '+(completed+1)+' / '+demos.cases.length+'：'+item.title;await requestChat(props.settings.backend,{...props.settings,workspaceId:demos.workspace_id,conversationId:item.conv_id,replyRequestId:crypto.randomUUID(),inputKind:'staff_action',replyAction:'custom'},prompts[item.id]);completed++;await refresh()}progress.value='已完成 '+completed+' 条真实示例调用，可在下方查看记录。'}catch(e){progress.value='已完成 '+completed+' 条；其余调用未继续执行。请先核对已有记录。';await refresh();error.value=e.message}finally{running.value=false}}
onMounted(()=>{refresh();timer=setInterval(()=>{if(!document.hidden)refresh()},5000)})
onUnmounted(()=>{disposed=true;clearInterval(timer)})
</script>
<template><section class="page monitor-panel"><header class="page-title"><div><h1>运行监控</h1><p>查看助手执行情况与实际调用记录；不代表客户问题解决率。</p></div><button type="button" class="secondary" :disabled="loading" @click="refresh">{{loading?'正在读取…':'刷新监控'}}</button></header><p v-if="error" role="alert" class="form-error">{{error}}</p><section class="monitor-examples"><div><h2>用完整案例跑一组真实调用</h2><p>物流晚到、缺件核验、规则解释，共3条。会实际调用当前配置的模型，追加到你的隔离演示记录。</p><small>每次点击执行一组；页面自动刷新仅查询统计，不会自动调用模型。</small></div><button type="button" class="primary" :disabled="running" @click="runExamples">{{running?'示例调用执行中…':'运行3条真实示例'}}</button><p v-if="progress" role="status" class="monitor-call-progress">{{progress}}</p></section><p v-if="!data&&!error" role="status">正在读取调用记录…</p><template v-if="data"><section class="monitor-history-summary"><h2>已记录的助手执行 · 跨重启保留</h2><div class="monitor-grid"><article><h3>累计执行</h3><strong>{{totals.total||0}}<small> 次</small></strong></article><article><h3>已完成</h3><strong>{{totals.completed||0}}<small> 次</small></strong></article><article><h3>示例调用</h3><strong>{{totals.examples||0}}<small> 次</small></strong></article><article><h3>平均执行耗时</h3><strong>{{totals.avg_elapsed_ms==null?'—':(totals.avg_elapsed_ms/1000).toFixed(2)+'s'}}</strong></article></div><p v-if="totals.failed||totals.pending||totals.degraded" class="source-note">部分完成 {{totals.degraded||0}} 次 · 执行异常 {{totals.failed||0}} 次 · 处理中或状态待核对 {{totals.pending||0}} 次</p></section><section class="monitor-call-history"><div class="section-heading"><h2>最近调用记录</h2><small>最近20条 · 每5秒查询更新</small></div><p v-if="!data.execution_calls?.recent.length" class="source-note">当前尚无已记录调用。运行一组示例，或在会话中翻译、准备回复后可在这里查看。</p><div v-else class="table-wrap"><table><thead><tr><th>时间</th><th>操作</th><th>来源</th><th>执行状态</th><th>回复Agent</th><th>耗时</th><th>查看</th></tr></thead><tbody><tr v-for="r in data.execution_calls.recent" :key="r.id"><td>{{display(r.started_at)}}</td><td>{{r.purpose}}<small v-if="r.example_template" class="monitor-example-label">{{exampleNames[r.example_template]||'演示案例'}}</small></td><td>{{sourceNames[r.source]||r.source}}</td><td>{{stateNames[r.state]||r.state}}</td><td>{{r.agent_types?.length?r.agent_types.map(a=>agentNames[a]||a).join("、"):"未记录执行对象"}}</td><td>{{r.elapsed_ms==null?'—':(r.elapsed_ms/1000).toFixed(2)+'s'}}</td><td><button v-if="r.can_open" type="button" class="text-button" @click="emit('openExample',{workspaceId:r.workspace_id,convId:r.conv_id})">查看关联会话</button><span v-else>—</span></td></tr></tbody></table></div></section><h2 class="monitor-runtime-heading">本次启动的 Agent 执行</h2><p class="source-note">{{data.runtime_scope}}。没有执行的 Agent 显示0，不补造调用。</p><div class="monitor-grid"><article v-for="[name,s] in Object.entries(data.agent_stats||{})" :key="name"><h2>{{agentNames[name]||name}}</h2><strong>{{s.total}}<small> 次执行</small></strong><dl><dt>请求执行成功率</dt><dd>{{s.total?(s.success_rate*100).toFixed(1)+'%':'—'}}</dd><dt>平均执行时长</dt><dd>{{s.total?(s.avg_ms/1000).toFixed(2)+'s':'—'}}</dd></dl></article></div><section class="monitor-details"><h2>知识检索工具 · 本次启动</h2><div v-for="[name,s] in Object.entries(data.tool_stats||{})" :key="name" class="tool-row"><strong>{{name}}</strong><span>{{s.total}} 次调用</span><span>熔断状态 {{s.circuit_state==='closed'?'正常':s.circuit_state}}</span></div><p class="source-note">示例使用隔离演示规则，未必经过知识检索工具；本地事实查询和缓存译文也不等于模型调用。</p><details><summary>统计口径与原始数据</summary><p>{{data.execution_calls?.scope}}</p><p>较早、尚未接入记录的执行不会回填为新调用。已完成表示执行流程返回结果，不评价回复是否正确。</p><pre>{{JSON.stringify(data,null,2)}}</pre></details><small>最近读取：{{display(lastUpdated)}}</small></section></template></section></template>
<style scoped>
.monitor-examples{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px;padding:22px;background:#eef2ff;border:1px solid #dce3f4;border-radius:10px;margin-bottom:26px}.monitor-examples h2{font-size:18px;margin:0 0 8px}.monitor-examples p{font-size:13px;line-height:1.8;margin:0 0 6px}.monitor-examples small,.monitor-call-history small{color:#61708a}.monitor-examples>div{flex:1;min-width:220px}.monitor-call-progress{flex-basis:100%;font-weight:600}.monitor-history-summary>h2,.monitor-call-history h2,.monitor-runtime-heading{font-size:18px}.monitor-history-summary .monitor-grid{grid-template-columns:repeat(4,minmax(0,1fr));margin:18px 0 28px}.monitor-history-summary h3{font-size:13px;font-weight:500;color:#64718b}.monitor-call-history{padding:22px;background:#fff;border:1px solid #dfe5ef;border-radius:10px;margin-bottom:30px}.monitor-call-history td{white-space:normal;overflow-wrap:anywhere;min-width:85px}.monitor-call-history table{min-width:640px}.monitor-runtime-heading{margin-top:30px}.monitor-example-label{display:block;margin-top:4px}.monitor-panel button{min-height:40px}@media(max-width:800px){.monitor-history-summary .monitor-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.monitor-call-history{padding:16px}.monitor-example-label{display:block;margin-top:4px}.monitor-panel button{min-height:44px}.monitor-examples{padding:18px}}
</style>
